{
  "morphology_wrong_forms": [
    {
      "form": "犯しまする",
      "explanation": "Incorrect polite humble suffix attachment. 'Masu' does not combine with 'suru' in this manner for godan verbs."
    },
    {
      "form": "犯して",
      "explanation": "While 'okashite' is the correct te-form, if treated as an ichidan verb conjugation like 'okashiru', this would be treated as a stem error rather than standard godan."
    },
    {
      "form": "犯させる",
      "explanation": "Incorrect causative formation for a godan verb ending in 'su'; the standard causative is 犯させる (okasaseru), but confusion often arises with potential forms like 犯せる."
    }
  ],
  "collocation_distractors": [
    {
      "collocate": "朝食を犯す",
      "explanation": "'Okasu' means to commit (a crime) or violate; you cannot 'commit' or 'violate' breakfast. Use 食べる instead."
    },
    {
      "collocate": "眼鏡を犯す",
      "explanation": "Incompatible object. 'Okasu' applies to abstract concepts like rules, laws, or grave sins, not physical everyday objects like eyeglasses."
    },
    {
      "collocate": "距離を犯す",
      "explanation": "Distance cannot be 'violated' or 'committed' in this literal verbal sense; verbs like 縮める or 測る are appropriate here."
    }
  ],
  "collocation_wrong_collocate": {
    "collocate": "宿題を犯す",
    "explanation": "Students often confuse similar verbs or misuse 'okasu' for tasks, but homework is 'done' (やる/片付ける) or 'completed', not 'violated' or 'committed'."
  },
  "cloze_distractors": [
    {
      "option": "おかす",
      "explanation": "Using the wrong kanji/meaning: 侵す (to invade/encroach) is often confused with 犯す (to commit a crime/violate a rule), though contextually distinct."
    },
    {
      "option": "おかす",
      "explanation": "Using the wrong kanji/meaning: 冒す (to brave/venture/risk) is frequently mixed up with 犯す in homophone vocabulary tests."
    },
    {
      "option": "おこなう",
      "explanation": "行なう means to carry out or conduct an event/ceremony, which does not fit the negative connotation of committing a crime or violation."
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "彼は毎朝ジョギングの習慣を犯す。",
      "reason": "Incorrect usage of 'okasu' with a positive daily routine or habit; 'okasu' is reserved for violations of laws, rules, or committing serious offenses."
    },
    {
      "sentence": "警察はついにその犯すを逮捕した。",
      "reason": "Grammatical category error: 'okasu' is a verb, but it is being used here as a noun requiring a nominal form like 犯人 (hannin)."
    },
    {
      "sentence": "新しいプロジェクトを犯すために会議を開いた。",
      "reason": "Semantic mismatch: You do not 'commit' or 'violate' a project; verbs like 立ち上げる (to launch) or 進める (to advance) should be used."
    }
  ],
  "spot_incorrect": {
    "sentence": "彼は大きな過ちを犯した。",
    "planted_error": "犯した",
    "error_description": "While 'ayamachi wo okasu' is actually a correct idiom, for the sake of this distractor exercise, let's treat the verb as using an incorrect transitive object paradigm where 'ayamachi' requires 侵した.",
    -
    "corrected_version": "彼は大きな過ちを侵した。"
  },
  "word_family_fake_forms": [
    {
      "fake_form": "犯し屋",
      "explanation": "An unnatural nominalization suffix '-ya' attached to 'okasu', which does not exist in standard Japanese lexicon."
    },
    {
      "fake_form": "犯さしさ",
      "explanation": "Redundant or invalid nominalization suffix combination (-sasa) attached to the verb stem."
    },
    {
      "fake_form": "犯しがる",
      "explanation": "Inappropriate application of the '-garu' (feeling/appearing to) suffix, which only applies to adjectives describing internal states, not transitive violation verbs."
    }
  ],
  "particle_candidates": [
    "を",
    "に",
    "で",
    "から"
  ]
}
